	@Override
	public Domain getDomain(String name) {
		return domains.get(name);
	}

	@Override
	public Table getTable(String schema, String name) {
		return SCHEMA.equals(schema) ? tables.get(name) : null;
	}

	@Override
	public List<String> getAllDomainNames() {
		return List.copyOf(domains.keySet());
	}

	@Override
	public List<String> getAllTableNames(String schema) {
		return SCHEMA.equals(schema) ? List.copyOf(tables.keySet()) : List.of();
	}

	/**
	 * Defines a domain.
	 *
	 * @param name        The name.
	 * @param type        The type.
	 * @param length      The length, -1 if not applicable.
	 * @param decimals    The decimals, -1 if not applicable.
	 * @param header      The header, or null.
	 * @param label       The label, or null.
	 * @param description The description, or null.
	 */
	private void domain(String name, Types type, int length, int decimals, String header, String label, String description) {
		Domain domain = new Domain(name, type, length, decimals);
		if (header != null) {
			domain.setHeader(header);
		}
		if (label != null) {
			domain.setLabel(label);
		}
		if (description != null) {
			domain.setDescription(description);
		}
		domains.put(name, domain);
	}

	/**
	 * Adds a column to a table, from a domain.
	 *
	 * @param table       The table.
	 * @param name        The column name.
	 * @param domain      The domain name.
	 * @param header      The header that overrides the domain one, or null.
	 * @param label       The label that overrides the domain one, or null.
	 * @param description The description that overrides the domain one, or
	 *                    null.
	 */
	private void column(Table table, String name, String domain, String header, String label, String description) {
		Column column = new Column(name, domains.get(domain));
		if (header != null) {
			column.setHeader(header);
		}
		if (label != null) {
			column.setLabel(label);
		}
		if (description != null) {
			column.setDescription(description);
		}
		table.columns().add(column);
	}

	/**
	 * Sets the primary key of a table. Its columns of nullable types become not
	 * nullable.
	 *
	 * @param table   The table.
	 * @param columns The column names.
	 */
	private static void primaryKey(Table table, String... columns) {
		Index index = new Index(table);
		index.addColumns(columns);
		for (Column column : index.getColumns()) {
			column.setNullable(false);
		}
		table.setPrimaryKey(index);
	}

	/**
	 * Adds a secondary index to a table.
	 *
	 * @param table   The table.
	 * @param columns The column names.
	 */
	private static void index(Table table, String... columns) {
		Index index = new Index(table);
		index.addColumns(columns);
		table.addIndex(index);
	}

